SINA_SMART["biochem1-carbohydrates"] = {"lecture":"biochem1-carbohydrates","title":"Carbohydrates: structure and classification","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"biochem1-carbohydrates:e0","text":"Carbohydrate: polyhydroxylated + one carbonyl (aldose or ketose).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e1","text":"Roles: energy, structure, nucleic acids, metabolism.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e2","text":"CₙH₂ₙOₙ; trioses, pentoses (ribose), hexoses (glucose, fructose).","topic":"Monosaccharides and isomers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e3","text":"D-sugars predominate; epimers differ at one carbon.","topic":"Monosaccharides and isomers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e4","text":"Cyclisation → α/β anomers.","topic":"Monosaccharides and isomers","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e5","text":"Sucrose (Glc α1-2β Fru) non-reducing; lactose (Gal β1-4 Glc) and maltose (Glc α1-4 Glc) reducing.","topic":"Disaccharides and reducing sugars","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e6","text":"Fehling test: brick-red precipitate with reducing sugars.","topic":"Disaccharides and reducing sugars","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e7","text":"Glycogen: α1-4 + α1-6 branches; liver and muscle.","topic":"Polysaccharides","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e8","text":"Cellulose: β1-4, indigestible fibre.","topic":"Polysaccharides","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"biochem1-carbohydrates:e9","text":"GAGs (hyaluronic acid, chondroitin sulphate) form proteoglycans.","topic":"Polysaccharides","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1d1vftg":"a","u6hk9k":"a","1cgd4s8":"a","1gcdwij":"a","a4ig18":"a","18uyoxa":"a","6fzte7":"a","1320hf6":"a","2ygddf":"a","ig0e7m":"a","wdeget":"a","3ai1s4":"a","hl9ezv":"a","mrdnrs":"x"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"biochem1-carbohydrates:e0":{"s":0,"u":["Carbohydrate: polyhydroxylated + one carbonyl (aldose or ketose).","Carbohydrates (sugars, saccharides, oses) are hydrophilic organic molecules: polyhydroxylated chains with one carbonyl group: an aldehyde ( aldose ) or a ketone ( ketose )."],"dp":[]},"biochem1-carbohydrates:e1":{"s":0,"u":["Roles: energy, structure, nucleic acids, metabolism.","Roles: energy (primary fuel; glycaemia), structure (cartilage), components of DNA/RNA and other biomolecules, and metabolism."],"dp":[]},"biochem1-carbohydrates:e2":{"s":1,"u":["CₙH₂ₙOₙ; trioses, pentoses (ribose), hexoses (glucose, fructose).","By carbons: trioses (glyceraldehyde, dihydroxyacetone), pentoses (ribose, deoxyribose: RNA/DNA), hexoses (glucose, galactose, mannose: aldoses; fructose: ketose).","Epimers differ at only one carbon (glucose and galactose at C4; glucose and mannose at C2)."],"dp":[]},"biochem1-carbohydrates:e3":{"s":1,"u":["D-sugars predominate; epimers differ at one carbon.","Epimers differ at only one carbon (glucose and galactose at C4; glucose and mannose at C2).","D/L stereoisomers : D-sugars predominate biologically."],"dp":[]},"biochem1-carbohydrates:e4":{"s":1,"u":["Cyclisation → α/β anomers.","In solution sugars cyclise by an intramolecular hemiacetal (aldoses) or hemiketal (ketoses) reaction, creating a new chiral anomeric carbon with two anomers, α and β ."],"dp":[]},"biochem1-carbohydrates:e5":{"s":2,"u":["Sucrose (Glc α1-2β Fru) non-reducing; lactose (Gal β1-4 Glc) and maltose (Glc α1-4 Glc) reducing.","Disaccharides (C₁₂H₂₂O₁₁): sucrose = glucose + fructose (α1-2β), non-reducing (no free anomeric OH); lactose (milk sugar) = galactose + glucose (β1-4), reducing ; lactase deficiency causes lactose intolerance ; maltose = glucose + glucose (α1-4)."],"dp":[]},"biochem1-carbohydrates:e6":{"s":2,"u":["Fehling test: brick-red precipitate with reducing sugars.","A reducing sugar has a free anomeric OH (cyclic) or free carbonyl (linear) and gives a positive Fehling test (Cu²⁺ reduced to a brick-red Cu₂O precipitate)."],"dp":[]},"biochem1-carbohydrates:e7":{"s":3,"u":["Glycogen: α1-4 + α1-6 branches; liver and muscle.","Homopolysaccharides (one monomer): glycogen (glucose, ~50,000 units; α1-4 chains with α1-6 branches; animal storage in liver and muscle ), starch (plant storage: amylose, linear, + amylopectin, branched), cellulose (glucose, β1-4 ; plant structure; undigested by humans; aids intestinal transit)."],"dp":[]},"biochem1-carbohydrates:e8":{"s":3,"u":["Cellulose: β1-4, indigestible fibre."],"dp":[{"h":"Why cellulose passes through us","t":"Starch and cellulose are both chains of glucose, but starch uses α bonds and cellulose β bonds. Human digestive enzymes cut α1-4 bonds only, so cellulose passes undigested as dietary fibre, adding bulk that speeds intestinal transit. Herbivores rely on gut microbes with β-glucosidases to digest it. Source: the lecture's polysaccharides slides."}]},"biochem1-carbohydrates:e9":{"s":3,"u":["GAGs (hyaluronic acid, chondroitin sulphate) form proteoglycans.","Heteropolysaccharides = glycosaminoglycans (GAGs) : two or more monomer types, bound to proteins as proteoglycans : hyaluronic acid (cartilage, tendons, vitreous humour, synovial fluid), chondroitin sulphate (tensile strength of cartilage, tendons, arteries), keratan sulphate."],"dp":[]}},"meta":{"1d1vftg":{"a":"recall","vg":"biochem1-carbohydrates:e0/recall/1"},"u6hk9k":{"a":"recall","vg":"biochem1-carbohydrates:e2/recall/1"},"1cgd4s8":{"a":"recall","vg":"biochem1-carbohydrates:e2/recall/1"},"1gcdwij":{"a":"relationship","vg":"biochem1-carbohydrates:e3/relationship/1"},"a4ig18":{"a":"recall","vg":"biochem1-carbohydrates:e4/recall/1"},"18uyoxa":{"a":"recall","vg":"biochem1-carbohydrates:e2/recall/2"},"6fzte7":{"a":"relationship","vg":"biochem1-carbohydrates:e5/relationship/1"},"1320hf6":{"a":"recall","vg":"biochem1-carbohydrates:e5/recall/1"},"2ygddf":{"a":"recall","vg":"biochem1-carbohydrates:e6/recall/1"},"ig0e7m":{"a":"recall","vg":"biochem1-carbohydrates:e7/recall/1"},"wdeget":{"a":"recall","vg":"biochem1-carbohydrates:e7/recall/2"},"3ai1s4":{"a":"recall","vg":"biochem1-carbohydrates:e8/recall/1"},"hl9ezv":{"a":"recall","vg":"biochem1-carbohydrates:e9/recall/1"}},"explRev":"d5a9692d498b"};
